WITH eligible AS (SELECT s.* FROM products s WHERE NOT EXISTS (SELECT 1 FROM store_sales c WHERE c.product_id = s.id AND c.sale_date >= '2024-10-01')) SELECT s.id, s.product_name, s.category, s.price, s.cost, s.stock_qty, s.launch_date, s.tags, s.supplier_id, (SELECT SUM(p2.stock_qty) FROM products p2 WHERE p2.supplier_id = s.supplier_id) AS sum_product_stock_qty FROM eligible s ORDER BY sum_product_stock_qty DESC, id DESC;
